	lnHosts := make([]string, 0, len(sblock.pile))
	for _, cfgVal := range sblock.pile["bind"] {
		lnHosts = append(lnHosts, cfgVal.Value.([]string)...)
	}
	if len(lnHosts) == 0 {
		if defaultBind, ok := options["default_bind"].(string); ok {
			lnHosts = []string{defaultBind}
		} else {
			lnHosts = []string{""}
		}
	}

	if len(sblock.pile["bind"]) > 0 {
		bindTokens := make([]caddyfile.Token, 0)
		for _, seg := range sblock.block.Segments {
			if len(seg) > 0 && seg[0].Text == "bind" {
				bindTokens = append(bindTokens, seg...)
			}
		}
		bindDispenser := caddyfile.NewDispenser(bindTokens)
		for bindDispenser.Next() {
			lnHosts = append(lnHosts, bindDispenser.RemainingArgs()...)
		}
	}

	listeners := make(map[string]struct{})
	for _, host := range lnHosts {
		network, parsedHost, parsedPort, splitErr := caddy.SplitNetworkAddress(host)
		unixListener := false
		if splitErr == nil {
			if network == "unix" || network == "unixgram" || network == "unixpacket" {
				parsedAddr := caddy.NetworkAddress{
					Network: network,
					Host:    parsedHost,
				}
				unixListener = parsedAddr.IsUnixNetwork()
			} else if parsedPort != "" {
				ports := strings.SplitN(parsedPort, "-", 2)
				if len(ports) == 1 {
					ports = append(ports, ports[0])
				}
				start, startErr := strconv.ParseUint(ports[0], 10, 16)
				if startErr == nil {
					end, endErr := strconv.ParseUint(ports[1], 10, 16)
					if endErr == nil && end >= start {
						parsedAddr := caddy.NetworkAddress{
							Network:   network,
							Host:      parsedHost,
							StartPort: uint(start),
							EndPort:   uint(end),
						}
						unixListener = parsedAddr.IsUnixNetwork()
					}
				}
			}
		}
		if unixListener {
			listeners[host] = struct{}{}
		} else {
			listenerHost := host
			listenerSuffix := ":" + lnPort
			listeners[listenerHost+listenerSuffix] = struct{}{}
		}
	}

	// now turn map into list
	listenersList := make([]string, 0, len(listeners))
	for lnStr := range listeners {
		listenersList = append(listenersList, lnStr)
	}

	return listenersList, nil
}

